INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", 1201820007, 0, "", "", 0, "vo_travel_talk", "", "vo_travel_talk_20018_01", 21, 20182);
